const staticUrl="/static/images/";async function injectSVGsByClass(prefix="sg-",pathClass="svg-path"){const elements=document.querySelectorAll(`[class*="${prefix}"]`);for(const el of elements){const className=Array.from(el.classList).find(cls=>cls.startsWith(prefix));if(!className)continue;const url=`${staticUrl}${className}.svg`;console.log(url);try{const response=await fetch(url);const svgText=await response.text();const parser=new DOMParser;const svgDoc=parser.parseFromString(svgText,"image/svg+xml");const svgEl=svgDoc.querySelector("svg");svgEl.querySelectorAll("path").forEach(path=>{path.classList.add(pathClass)});el.appendChild(svgEl)}catch(err){console.error(`Failed to load ${url}:`,err)}}}injectSVGsByClass();